function drawDrop(ctx, x, y, size, color) {
  ctx.beginPath(); ctx.moveTo(x, y - size * .48);
  ctx.bezierCurveTo(x + size * .35, y - size * .05, x + size * .42, y + size * .25, x, y + size * .45);
  ctx.bezierCurveTo(x - size * .42, y + size * .25, x - size * .35, y - size * .05, x, y - size * .48);
  ctx.fillStyle = color; ctx.fill();
}

function drawFire(ctx, x, y, size, color) {
  ctx.beginPath(); ctx.moveTo(x, y - size * .48);
  ctx.bezierCurveTo(x + size * .08, y - size * .18, x + size * .46, y - size * .05, x + size * .28, y + size * .3);
  ctx.bezierCurveTo(x + size * .08, y + size * .55, x - size * .36, y + size * .42, x - size * .31, y + size * .08);
  ctx.bezierCurveTo(x - size * .27, y - size * .12, x - size * .05, y - size * .2, x, y - size * .48);
  ctx.fillStyle = color; ctx.fill();
}

function drawHeart(ctx, x, y, size, color) {
  ctx.beginPath(); ctx.moveTo(x, y + size * .4);
  ctx.bezierCurveTo(x - size * .55, y + size * .05, x - size * .45, y - size * .38, x - size * .18, y - size * .34);
  ctx.bezierCurveTo(x, y - size * .32, x, y - size * .12, x, y - size * .12);
  ctx.bezierCurveTo(x, y - size * .12, x, y - size * .32, x + size * .18, y - size * .34);
  ctx.bezierCurveTo(x + size * .45, y - size * .38, x + size * .55, y + size * .05, x, y + size * .4);
  ctx.fillStyle = color; ctx.fill();
}

