function renderRoomDebug(){if(typeof document==="undefined")return;const panel=document.getElementById("room-debug");if(!panel)return;const stats=document.getElementById("room-debug-stats"),components=document.getElementById("room-debug-components");stats.textContent=ROOM_STAT_KEYS.map(key=>`${key}: ${roomState.roomStats[key]}`).join("\n");components.textContent=roomParts().length?roomParts().map(part=>part.label).join(" · "):"无 component"}
function roomEvolutionHint(){if(roomState.evolutionId)return`客房主题：${roomState.evolutionName}`;const parts=roomParts();if(parts.some(part=>["moon-lamp","moonlight","memory-mirror"].includes(part.id)))return ROOM_EVOLUTION_RULES[0].hint;if(parts.some(part=>["fog-lamp","dream-fog","dream-bed"].includes(part.id)))return ROOM_EVOLUTION_RULES[1].hint;if(parts.some(part=>part.id==="mechanical-clock"||part.usageTags?.includes("mechanical")))return ROOM_EVOLUTION_RULES[2].hint;return"这间客房还可以继续布置。"}
function renderRoomState(){if(typeof document==="undefined")return;const stage=document.getElementById("room-stage"),itemsLayer=document.getElementById("room-items-layer"),empty=document.getElementById("room-empty");if(!itemsLayer)return;itemsLayer.replaceChildren();const parts=roomParts();empty.hidden=Boolean(parts.length);parts.forEach((part,index)=>{if(part.category==="atmosphere")return;const position=roomPartPosition(part,index),card=document.createElement("div");card.className=`room-part role-${part.roomRole} ${roomState.selectedPartId===part.runtimeId?"selected":""}`;card.dataset.partId=part.runtimeId;card.dataset.elementId=part.id;card.style.left=`${position.x}%`;card.style.top=`${position.y}%`;const visual=document.createElement("div");renderElementVisual(part,visual,40);const label=document.createElement("b");label.textContent=part.label;card.append(visual,label);attachRoomDrag(card,part,stage);itemsLayer.append(card)});calculateRoomStats();checkRoomEvolution();document.getElementById("room-stats").innerHTML=renderAttributeRows(roomState.roomStats,ROOM_STAT_KEYS);stage.dataset.evolution=roomState.evolutionId||"";stage.classList.toggle("has-wood-floor",parts.some(part=>part.id==="wood-floor"));stage.classList.toggle("has-fog-window",parts.some(part=>part.id==="fog-window"));document.getElementById("room-type").textContent=roomState.roomType==="empty"?"基础客房":roomState.roomType;document.getElementById("evolution-hint").textContent=roomEvolutionHint();renderRoomEffects();renderRoomDebug();renderStorage();if(questState.active)questState.lastEvaluation=checkRequestCompletion()}

function performReaction(firstIndex, secondIndex, resultId) {
  const first=reactorState.bodies[firstIndex],second=reactorState.bodies[secondIndex];
  if(!first||!second||first.isRemoved||second.isRemoved||first.isLocked||second.isLocked)return false;
  first.isLocked=second.isLocked=true;first.state=second.state="REACTION_LOCKED";first.isMerging=second.isMerging=true;first.isRemoved=second.isRemoved=true;
  const x=(first.x+second.x)/2,y=(first.y+second.y)/2;
  const product=reactionResultFactory(first,second,resultId,x,y);product.vx=(first.vx+second.vx)/2;product.vy=Math.min(-1.3,(first.vy+second.vy)/2);product.mergeCooldown=24;
  reactorState.reactionAnimations.push({first:{...first},second:{...second},x,y,life:18,maxLife:18});reactorState.bodies=reactorState.bodies.filter(body=>!body.isRemoved);reactorState.bodies.push(product);reactorState.reactions+=1;reactorState.latestResult=product;
  spawnParticles(x,y,product);
  const isNewDiscovery=discoveryBook.record(product);
  const latestStep=product.reactionHistory.at(-1);reactorState.recentHistory.push(latestStep);reactorState.recentHistory=reactorState.recentHistory.slice(-5);
  markProgress();advanceTutorial("reaction",product.id);soundInterface.playReaction(product);
  if(product.resultType==="roomEvolution")routeRoomRole(product);
  if(typeof document!=="undefined"){showReactionToast(`${first.label} + ${second.label} → ${product.label}`,product.level);if(isNewDiscovery)showDiscoveryPop(product);renderLatestResult(product);renderRecentHistory();renderStats();renderElementDetail(product);updateOpportunityUI();hideHint();}
  return product;
}

function collisionAndReaction() {
  const bodies=reactorState.bodies;
  for(let i=0;i<bodies.length;i++)for(let j=i+1;j<bodies.length;j++){
    const a=bodies[i],b=bodies[j];if(a.isRemoved||b.isRemoved||a.isMerging||b.isMerging||a.mergeCooldown>0||b.mergeCooldown>0)continue;
    const distance=Math.hypot(b.x-a.x,b.y-a.y);if(distance>a.radius+b.radius+2)continue;
    const resultId=reactionRules[reactionKey(a.id,b.id)];if(resultId)return performReaction(i,j,resultId);
  }
  return false;
}

function resolvePhysicalCollisions(now=Date.now()){const bodies=reactorState.bodies;for(let i=0;i<bodies.length;i++)for(let j=i+1;j<bodies.length;j++){const a=bodies[i],b=bodies[j];if(a.isRemoved||b.isRemoved||a.isGrabbed||b.isGrabbed||a.isRoomBound||b.isRoomBound)continue;const dx=b.x-a.x,dy=b.y-a.y,d=Math.hypot(dx,dy)||.001,min=a.radius+b.radius;if(d>=min)continue;const pair=[a.runtimeId,b.runtimeId].sort().join("|");if(canReact(a,b)&&!reactorState.reactionPreview&&now>=(reactorState.reactionPreviewCooldowns.get(pair)||0))reactorState.reactionPreview={first:a,second:b,pair,startedAt:now,expiresAt:now+1000};const nx=dx/d,ny=dy/d,overlap=min-d;a.x-=nx*overlap*.5;a.y-=ny*overlap*.5;b.x+=nx*overlap*.5;b.y+=ny*overlap*.5;const relative=(b.vx-a.vx)*nx+(b.vy-a.vy)*ny;if(relative<0){const impulse=-(1.2*relative)/2;a.vx-=impulse*nx;a.vy-=impulse*ny;b.vx+=impulse*nx;b.vy+=impulse*ny;}}if(reactorState.reactionPreview&&now>reactorState.reactionPreview.expiresAt){reactorState.reactionPreviewCooldowns.set(reactorState.reactionPreview.pair,now+1800);reactorState.reactionPreview=null}return reactorState.reactionPreview}

function updatePhysics(delta){const canvas=reactorState.canvas;if(!canvas)return;for(const body of reactorState.bodies){body.mergeCooldown=Math.max(0,body.mergeCooldown-delta);body.birthPulse=Math.max(0,(body.birthPulse||0)-delta);if(body.roomFlight)body.roomFlight.life=Math.max(0,body.roomFlight.life-delta);if(body.isGrabbed||body.isRoomBound)continue;body.vy+=.2*delta;body.x+=body.vx*delta;body.y+=body.vy*delta;body.vx*=.998;if(body.x-body.radius<7){body.x=7+body.radius;body.vx=Math.abs(body.vx)*.4}if(body.x+body.radius>canvas.width-7){body.x=canvas.width-7-body.radius;body.vx=-Math.abs(body.vx)*.4}if(body.y+body.radius>canvas.height-7){body.y=canvas.height-7-body.radius;body.vy=Math.abs(body.vy)<.7?0:body.vy*-.24;body.vx*=.96}}for(const p of reactorState.particles){p.life-=delta;p.x+=p.vx*delta;p.y+=p.vy*delta;p.vx*=.97;p.vy=p.vy*.97+.02*delta}reactorState.particles=reactorState.particles.filter(p=>p.life>0);for(const effect of reactorState.failureFeedbacks)effect.life-=delta;reactorState.failureFeedbacks=reactorState.failureFeedbacks.filter(effect=>effect.life>0);for(const effect of reactorState.discardAnimations)effect.life-=delta;reactorState.discardAnimations=reactorState.discardAnimations.filter(effect=>effect.life>0);for(const effect of reactorState.reactionAnimations)effect.life-=delta;reactorState.reactionAnimations=reactorState.reactionAnimations.filter(effect=>effect.life>0);resolvePhysicalCollisions();}

function spawnParticles(x,y,element){const count=14+element.level*8,color=colorFor(element);for(let i=0;i<count;i++){const a=Math.PI*2*i/count+Math.random()*.2,s=2+Math.random()*(2.2+element.level*.3);reactorState.particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,color,life:38+element.level*5,maxLife:65,r:2+Math.random()*(2+element.level*.2)});}}

function renderCanvas(){
  const {ctx,canvas}=reactorState;if(!ctx||!canvas)return;ctx.clearRect(0,0,canvas.width,canvas.height);
  const candidate=reactorState.reactionCandidate;
  if(candidate){const glow=5+Math.sin(performance.now()/100)*3;ctx.save();ctx.strokeStyle="rgba(65,132,107,.85)";ctx.lineWidth=4;ctx.shadowColor="#4d9d7d";ctx.shadowBlur=18+glow;ctx.beginPath();ctx.arc(candidate.x,candidate.y,candidate.radius+10+glow,0,Math.PI*2);ctx.stroke();ctx.fillStyle="#395f50";ctx.font='700 18px sans-serif';ctx.textAlign="center";ctx.fillText("?",candidate.x,candidate.y-candidate.radius-17);ctx.restore()}
  const highlighted=new Map(reactorState.libraryPreviewTargets.map(item=>[item.runtimeId,item.known]));for(const id of reactorState.grabTargets)highlighted.set(id,true);for(const body of reactorState.bodies){if(!highlighted.has(body.runtimeId))continue;ctx.save();ctx.strokeStyle=highlighted.get(body.runtimeId)?"#69c99c":"#a8b7ad";ctx.lineWidth=reactorState.grabTargets.includes(body.runtimeId)?5:2;ctx.setLineDash(highlighted.get(body.runtimeId)?[]:[5,5]);ctx.shadowColor="#78c9a4";ctx.shadowBlur=reactorState.grabTargets.includes(body.runtimeId)?24:10;ctx.beginPath();ctx.arc(body.x,body.y,body.radius+10,0,Math.PI*2);ctx.stroke();ctx.fillStyle="#435f52";ctx.font='700 16px sans-serif';ctx.textAlign="center";ctx.fillText(highlighted.get(body.runtimeId)?"✓":"?",body.x,body.y-body.radius-14);ctx.restore()}
  const preview=reactorState.reactionPreview;if(preview){const midX=(preview.first.x+preview.second.x)/2,midY=(preview.first.y+preview.second.y)/2;ctx.save();ctx.strokeStyle="#d7aa61";ctx.lineWidth=4;ctx.setLineDash([8,5]);ctx.beginPath();ctx.moveTo(preview.first.x,preview.first.y);ctx.lineTo(preview.second.x,preview.second.y);ctx.stroke();ctx.fillStyle="#fff8df";ctx.beginPath();ctx.arc(midX,midY,20,0,Math.PI*2);ctx.fill();ctx.fillStyle="#765b31";ctx.font='800 19px sans-serif';ctx.textAlign="center";ctx.fillText("?",midX,midY+6);ctx.restore()}
  const bodies=[...reactorState.bodies].sort((a,b)=>Number(a.isGrabbed)-Number(b.isGrabbed));
  for(const body of bodies){
    const pulse=1+(body.birthPulse||0)/34*(.08+body.level*.025);const flight=body.roomFlight;const flightProgress=flight?1-flight.life/flight.maxLife:0;const drawX=flight?flight.startX+(flight.targetX-flight.startX)*flightProgress:body.x;const drawY=flight?flight.startY+(flight.targetY-flight.startY)*flightProgress:body.y;const grabbedScale=body.isGrabbed?1.14:(flight?Math.max(.18,1-flightProgress*.82):1);
    ctx.save();if(body.isGrabbed){ctx.shadowColor="rgba(32,46,39,.42)";ctx.shadowBlur=28;ctx.translate(0,-4)}drawElementPlate(ctx,body,drawX,drawY,body.radius*1.75*pulse*grabbedScale);ctx.restore();
    if(reactorState.selectedBodyId===body.runtimeId&&!body.isGrabbed){ctx.save();ctx.strokeStyle="#526a66";ctx.setLineDash([4,4]);ctx.lineWidth=2;ctx.beginPath();ctx.arc(body.x,body.y,body.radius+7,0,Math.PI*2);ctx.stroke();ctx.restore()}
    ctx.save();ctx.globalAlpha=flight?1-flightProgress:.92;ctx.fillStyle="rgba(32,38,34,.82)";ctx.font=`700 ${body.level>=4?12:11}px "Microsoft YaHei",sans-serif`;ctx.textAlign="center";ctx.fillText(body.label,drawX,drawY+body.radius*.72,body.radius*1.75);if(body.roomRole){ctx.fillStyle="#526a66";ctx.font='700 8px sans-serif';ctx.fillText(body.roomRole.toUpperCase(),drawX,drawY-body.radius*.68)}ctx.restore();
  }
  for(const effect of reactorState.reactionAnimations){const scale=effect.life/effect.maxLife;const turn=(1-scale)*.55;for(const old of [effect.first,effect.second]){ctx.save();ctx.translate(effect.x,effect.y);ctx.rotate((old===effect.first?-1:1)*turn);ctx.translate(-effect.x,-effect.y);drawElementPlate(ctx,old,old.x+(effect.x-old.x)*(1-scale),old.y+(effect.y-old.y)*(1-scale),old.radius*1.75*scale,scale);ctx.restore()}}
  for(const effect of reactorState.failureFeedbacks){const progress=1-effect.life/effect.maxLife;ctx.save();ctx.globalAlpha=effect.life/effect.maxLife;ctx.strokeStyle="#8c968e";ctx.lineWidth=2;ctx.beginPath();ctx.arc(effect.x,effect.y,12+progress*25,0,Math.PI*2);ctx.stroke();ctx.font='700 16px sans-serif';ctx.fillStyle="#7b857e";ctx.textAlign="center";ctx.fillText("×",effect.x,effect.y+5);ctx.restore()}
  for(const effect of reactorState.discardAnimations){const scale=effect.life/effect.maxLife;drawElementPlate(ctx,effect,effect.x,effect.y+(1-scale)*32,effect.radius*1.75*scale,scale)}
  for(const p of reactorState.particles){ctx.save();ctx.globalAlpha=Math.min(1,p.life/p.maxLife);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fill();ctx.restore()}
  if(reactorState.guideVisible&&reactorState.selectedId&&!reactorState.grabbedBody){const e=elementLibrary[reactorState.selectedId];ctx.save();ctx.strokeStyle="rgba(92,119,104,.35)";ctx.setLineDash([6,7]);ctx.beginPath();ctx.moveTo(reactorState.aimX,60);ctx.lineTo(reactorState.aimX,canvas.height-12);ctx.stroke();ctx.restore();drawElementPlate(ctx,e,reactorState.aimX,38,62,.38)}
}
function animationLoop(time){const delta=Math.min((time-(reactorState.lastFrame||time))/16.67,2);reactorState.lastFrame=time;updatePhysics(delta||1);renderCanvas();window.requestAnimationFrame(animationLoop);}

function selectElement(id){reactorState.selectedId=id;if(typeof document!=="undefined"){document.querySelectorAll(".element-card").forEach(card=>card.classList.toggle("selected",card.dataset.id===id));document.getElementById("selected-label").textContent=elementLibrary[id].label;renderElementVisual(elementLibrary[id],document.getElementById("selected-preview"),54);previewPotentialReactions(id)}advanceTutorial("select",id)}
function activeBodies(){return reactorState.bodies.filter(body=>!body.isRemoved&&!body.isRoomBound)}
function canSpawnElement(id){const active=activeBodies();if(active.length>=MAX_ACTIVE_ELEMENTS)return{ok:false,reason:"实验区已满，请先反应或清理元素。"};if(active.filter(body=>body.id===id).length>=MAX_SAME_ELEMENT)return{ok:false,reason:"场上已经有太多相同元素。"};if(!reactorState.canDrop)return{ok:false,reason:"试剂生成中，请稍候。"};return{ok:true,reason:""}}
function showLibraryMessage(text){if(typeof document==="undefined")return;const message=document.getElementById("library-message");message.textContent=text;window.clearTimeout(showLibraryMessage.timer);if(text)showLibraryMessage.timer=window.setTimeout(()=>{message.textContent=""},2400)}
function spawnSelected(x,y=38){if(!reactorState.selectedId)return false;const allowance=canSpawnElement(reactorState.selectedId);if(!allowance.ok){showLibraryMessage(allowance.reason);setInteractionStatus(allowance.reason);return false}const body=createBody(elementLibrary[reactorState.selectedId],Math.max(45,Math.min(reactorState.canvas.width-45,x)),y);reactorState.bodies.push(body);reactorState.canDrop=false;markProgress();advanceTutorial("spawn",body.id);if(typeof document!=="undefined"){showLibraryMessage("");document.getElementById("chamber-empty").hidden=true;updateOpportunityUI();window.setTimeout(()=>{reactorState.canDrop=true},SPAWN_COOLDOWN_MS)}else reactorState.canDrop=true;return body;}
function randomNext(){const available=getAvailableBaseIds();selectElement(available[Math.floor(Math.random()*available.length)]);showReactionToast(`下一元素：${elementLibrary[reactorState.selectedId].label}`,1);}

function renderElementPool(category="全部"){const pool=document.getElementById("element-pool");pool.replaceChildren();getAvailableBaseIds().map(id=>elementLibrary[id]).filter(e=>category==="全部"||e.libraryCategory===category).forEach(element=>{const card=document.createElement("button");card.type="button";card.className="element-card";card.dataset.id=element.id;card.draggable=true;card.style.setProperty("--element-color",colorFor(element));const visual=document.createElement("span");renderElementVisual(element,visual,62);const label=document.createElement("b");label.textContent=element.label;const dominant=ATTRIBUTE_KEYS.reduce((best,key)=>(element.attributes?.[key]||0)>(element.attributes?.[best]||0)?key:best,"light"),type=document.createElement("small");type.textContent=`${elementTypeLabel(element.elementType)} · ${ATTRIBUTE_META[dominant].icon} ${ATTRIBUTE_META[dominant].label}`;type.title=ATTRIBUTE_META[dominant].label;card.append(visual,label,type);card.addEventListener("click",()=>selectElement(element.id));card.addEventListener("dragstart",event=>{event.dataTransfer.setData("text/element-id",element.id);event.dataTransfer.effectAllowed="copy";selectElement(element.id)});pool.append(card)});updateOpportunityUI()}
function renderCategoryTabs(){const tabs=document.getElementById("category-tabs");CATEGORIES.forEach((category,index)=>{const button=document.createElement("button");button.type="button";button.textContent=category;button.classList.toggle("active",index===0);button.addEventListener("click",()=>{tabs.querySelectorAll("button").forEach(item=>item.classList.remove("active"));button.classList.add("active");renderElementPool(category)});tabs.append(button)});}

const CATEGORY_NAMES={material:"中间材料",component:"客房用品",atmosphere:"客房环境",evolution:"客房主题",base:"基础元素"};
const ATTRIBUTE_META=Object.freeze({light:{icon:"☀",label:"光照",color:"#c39b45"},warmth:{icon:"🔥",label:"温暖",color:"#bc704d"},dream:{icon:"🌙",label:"梦境",color:"#7d7895"},eerie:{icon:"👻",label:"灵异",color:"#66877f"},comfort:{icon:"🫧",label:"舒适",color:"#6d9085"},memory:{icon:"🧠",label:"记忆",color:"#84786b"}});
const ATTRIBUTE_UI=ATTRIBUTE_META;
const ATTRIBUTE_NAMES=Object.freeze(Object.fromEntries(ATTRIBUTE_KEYS.map(key=>[key,ATTRIBUTE_META[key].label])));
function attributeDots(value){const count=Math.max(0,Math.min(5,Math.round(Number(value)||0)));return"●".repeat(count)+"○".repeat(5-count)}
function renderAttributeRow(attrKey,value,options={}){const meta=ATTRIBUTE_META[attrKey];if(!meta)return"";const prefix=options.prefix?`<em>${options.prefix}</em>`:"",display=options.valueText??(options.before!==undefined?`${options.before} → ${options.after}`:attributeDots(value));return`<span class="attribute-row" data-attribute="${attrKey}" title="${meta.label}" style="--attribute-color:${meta.color}">${prefix}<i aria-hidden="true">${meta.icon}</i><strong>${meta.label}</strong><b class="attribute-value">${display}</b></span>`}
function renderAttributeRows(values={},keys=ATTRIBUTE_KEYS,options={}){return keys.map(key=>renderAttributeRow(key,values[key]||0,options[key]||options)).join("")}
function elementTypeLabel(type){return({nature:"自然",energy:"能量",material:"物质",spirit:"灵性",concept:"概念",object:"物件",space:"空间"})[type]||"未知"}
function attributeMarkup(element){return renderAttributeRows(element.attributes||{})}
function calculateTaskRelevance(element,request=campaignState.currentRequest){if(!request)return 0;let score=0,possible=0;for(const [key,rule] of Object.entries(request.requiredStats||{})){if(!ATTRIBUTE_KEYS.includes(key))continue;possible+=2;if((element.attributes?.[key]||0)>0)score+=1;if(rule.min!==undefined&&(element.attributes?.[key]||0)>=Math.min(rule.min,2))score+=1}const wanted=new Set([...(request.requiredItemTags||request.requiredRoomTags||[]),...(request.preferredItemTags||[]),...(request.inspectionTags||[])]);if(wanted.size){possible+=2;if(componentTags(element).some(tag=>wanted.has(tag)))score+=2}return possible?Math.max(0,Math.min(3,Math.ceil(score/possible*3))):1}
function elementDetailMarkup(element,{sheet=false}={}){const potential=reactionPotential(element),entries=reactionEntries(element.id),known=entries.filter(isReactionKnown),type=potential.canReactFurther?"中间产物":elementTypeLabel(element.elementType),progress=potential.canReactFurther?`${known.length} / ${known.length<entries.length?"?":entries.length}`:`${known.length} / ${entries.length}`,nearby=potential.nearby?'<p class="nearby-reaction">附近似乎有什么能和它反应……</p>':"",close=sheet?'<button class="detail-sheet-close" type="button" aria-label="关闭元素详情">关闭</button>':"";return`${close}<div class="detail-head"><div class="detail-sheet-visual" data-detail-visual></div><div><b>${element.label}</b><span>${type} · LEVEL ${element.level}</span></div></div>${continuationBadge(element)}<p>${element.personality||element.description}</p><div class="detail-attributes attribute-grid">${renderAttributeRows(element.attributes||{},ROOM_STAT_KEYS)}</div><p class="detail-tags"><b>标签：</b>${(element.tags||[]).map(tag=>TAG_META[tag]?.label||tag).join(" / ")||"待探索"}</p><p><b>当前实验室：${potential.nearby?`有 ${potential.nearby} 个可能反应对象`:"暂时没有可见反应对象"}</b></p><p><b>已发现反应 ${progress}</b></p>${potential.canReactFurther?"<p>可能还能继续变化。</p>":""}${nearby}<ul>${entries.map(entry=>isReactionKnown(entry)?`<li>✓ ${elementLibrary[entry.partnerId].label} → ${elementLibrary[entry.outputId].label}</li>`:`<li>? 未知对象 → ?????</li>`).join("")||"<li>暂无后续反应</li>"}</ul>`}
function renderElementDetail(element,{openSheet=false}={}){if(typeof document==="undefined"||!element)return;const root=document.getElementById("element-detail");root.innerHTML=elementDetailMarkup(element);if(!openSheet)return;const sheet=document.getElementById("mobile-detail-sheet"),content=document.getElementById("mobile-detail-content"),backdrop=document.getElementById("detail-sheet-backdrop");content.innerHTML=elementDetailMarkup(element,{sheet:true});const visual=content.querySelector("[data-detail-visual]");if(visual)renderElementVisual(element,visual,54);content.querySelector(".detail-sheet-close")?.addEventListener("click",closeElementDetailSheet);sheet.hidden=false;backdrop.hidden=false;document.body.classList.add("detail-sheet-open");previewLibraryElement(element.id,{render:false});window.clearTimeout(renderElementDetail.previewTimer);renderElementDetail.previewTimer=window.setTimeout(()=>{if(!sheet.hidden&&!reactorState.grabbedBody)reactorState.libraryPreviewTargets=[]},2800)}
function openElementDetailSheet(element){renderElementDetail(element,{openSheet:true})}
function closeElementDetailSheet(){if(typeof document==="undefined")return;document.getElementById("mobile-detail-sheet").hidden=true;document.getElementById("detail-sheet-backdrop").hidden=true;document.body.classList.remove("detail-sheet-open");if(!reactorState.grabbedBody)reactorState.libraryPreviewTargets=[]}
function updateOpportunityUI(){if(reactorState.selectedId)reactorState.libraryPreviewTargets=activeBodies().filter(body=>reactionRules[reactionKey(reactorState.selectedId,body.id)]).map(body=>({runtimeId:body.runtimeId,known:discoveryBook.discovered.has(reactionRules[reactionKey(reactorState.selectedId,body.id)])}));if(typeof document==="undefined")return;document.querySelectorAll(".element-card").forEach(card=>{const count=availableReactionCount(card.dataset.id),element=elementLibrary[card.dataset.id],relevance=calculateTaskRelevance(element);card.dataset.opportunities=String(count);card.dataset.relevance=String(relevance);card.classList.toggle("has-opportunity",count>0);let badge=card.querySelector(".opportunity-badge");if(!badge){badge=document.createElement("i");badge.className="opportunity-badge";card.append(badge)}badge.textContent=count?`${count} 个机会`:""});if(reactorState.opportunitySort){const pool=document.getElementById("element-pool"),cards=[...pool.children];cards.sort((a,b)=>(+b.dataset.opportunities)-(+a.dataset.opportunities)||(+b.dataset.relevance)-(+a.dataset.relevance));cards.forEach(card=>pool.append(card))}}
function previewLibraryElement(id,{render=true}={}){reactorState.libraryPreviewTargets=activeBodies().filter(body=>reactionRules[reactionKey(id,body.id)]).map(body=>({runtimeId:body.runtimeId,known:discoveryBook.discovered.has(reactionRules[reactionKey(id,body.id)])}));if(render)renderElementDetail(elementLibrary[id]);return reactorState.libraryPreviewTargets}
function recalculateLibraryReactionOpportunities(){updateOpportunityUI();return Object.fromEntries(getAvailableBaseIds().map(id=>[id,availableReactionCount(id)]))}
function previewPotentialReactions(element){const id=typeof element==="string"?element:element.id;previewLibraryElement(id);return reactorState.libraryPreviewTargets}
function predictRoomStats(element){const before={...roomState.roomStats},after={...before};for(const key of ROOM_STAT_KEYS)after[key]=Math.max(0,Math.min(5,after[key]+(Number(element?.attributes?.[key])||0)));return{before,after}}
function renderRoomPrediction(element){if(typeof document==="undefined")return;const panel=document.getElementById("room-prediction");if(!element){panel.hidden=true;return}const {before,after}=predictRoomStats(element);panel.hidden=false;panel.querySelector("div").innerHTML=ROOM_STAT_KEYS.map(key=>renderAttributeRow(key,after[key],{before:before[key],after:after[key]})).join("")}
