const USAGE_NAMES={lighting:"照明",warm:"供暖",floor:"铺设地面",wall:"墙面布置",window:"窗区",door:"入口",furniture:"家具",centerpiece:"中央装置",atmosphere:"客房环境",dream:"梦境效果",memory:"怀旧效果",calm:"安静休息",soft:"休息用途",mechanical:"机械用途",eerie:"怪异效果",structure:"客房结构",spiritual:"灵性用途",cold:"冷感效果",upgrade:"继续合成"};
