  const grid=document.getElementById("discovery-grid");grid.replaceChildren();document.getElementById("product-total").textContent=`${discoveryBook.discovered.size} / ${productIds.length}`;document.getElementById("discovery-count").textContent=String(discoveryBook.discovered.size);
