    const title=document.createElement("h3");title.textContent=known?definition.label:"?????";const formula=document.createElement("p");formula.className="formula";formula.textContent=known?.firstRecipe?.label||"配方未知";const description=document.createElement("p");description.textContent=known?definition.description:"尚未发现";copy.append(level,title,formula,description);
    if(known){const attributes=document.createElement("div");attributes.className="discovery-attributes attribute-grid";attributes.innerHTML=renderAttributeRows(definition.attributes||{});const usage=document.createElement("p");usage.className="usage";usage.textContent=usageSummary(definition);copy.append(attributes,usage);if(definition.canReactFurther){const badge=document.createElement("span");badge.className="continuation-badge";badge.textContent="↗ 还能继续反应";copy.append(badge)}card.tabIndex=0;card.addEventListener("click",()=>renderElementDetail(definition))}
    card.append(visual,copy);grid.append(card)
