const STAT_NAMES={light:"光照",warmth:"温暖",dream:"梦境",eerie:"灵异",comfort:"舒适",memory:"记忆"};
const REPEAT_GUEST_LEADS=Object.freeze({child:"我还记得这里。", "oddity-lover":"我又来了，这次也别给我普通东西。",insomniac:"我之前在这里住过，今晚再试一次。",elder:"上回来住过以后，我还记得这里的样子。",mechanic:"上次的结构我看过了，这回要求再细一点。",dreamwalker:"我好像来过……也可能是在梦里。","cold-guest":"我又来了，先说好，这次也别让我挨冻。",mystery:"我们见过。别问是在门的哪一边。"});
function rememberedComponentLead(npc,archive){const last=archive?.solutionHistory?.at(-1),used=last?.usedComponents||[];if(!used.length||(archive.attemptCount||0)%2!==0)return null;const component=used.find(item=>item.roomRole==="light")||used.find(item=>item.id?.includes("bed"))||used.find(item=>item.roomRole==="door"||item.id?.includes("clock"))||used[0];if(!component)return null;const noun=component.roomRole==="light"?"上次床边那盏灯":component.id?.includes("bed")?"上回那张床":component.roomRole==="door"?"上次那扇门":component.id?.includes("clock")?"上回那个钟":`上次那个${component.label}`;const endings={child:"我还记得。",insomniac:"我睡过以后还记得。",elder:"我一直没忘。",mechanic:"我已经看过它的结构。",dreamwalker:"还留在梦里。","cold-guest":"至少那晚没让我一直发抖。","oddity-lover":"我回去以后还想了半天。",mystery:"它记得我。"};return`${noun}，${endings[npc.id]||"我还记得。"}`}
function requestDialogueForVisit(npc,request,archive=customerArchive.get(npc?.id)){const returning=(request?.day||1)>1&&((archive?.attemptCount||0)>0||(archive?.solutionHistory?.length||0)>0);if(!returning)return request?.dialogue||"";const lead=rememberedComponentLead(npc,archive)||REPEAT_GUEST_LEADS[npc.id]||"我之前来住过。";return`${lead}\n${request.dialogue}`}
const QUEUE_TIMING=Object.freeze({enter:1000,inspect:1000,emotion:700,feedbackPause:500,leave:1400,clearStep:220});
function requestTags(request){if(request.difficulty>=4)return["需求含糊","留意住起来的感觉","没有唯一答案"];const tags=[];for(const [key,rule] of Object.entries(request.requiredStats||{})){const prefix=`${ATTRIBUTE_UI[key]?.icon||""} ${STAT_NAMES[key]||key}`;if(rule.min!==undefined)tags.push(`${prefix} ${attributeDots(rule.min)}`);if(rule.max!==undefined)tags.push(`${prefix} 不高于 ${attributeDots(rule.max)}`)}for(const [key,rule] of Object.entries(request.dislikedStats||{}))tags.push(`避免 ${ATTRIBUTE_UI[key]?.icon||""} ${STAT_NAMES[key]||key} ${attributeDots(rule.min||0)}`);return tags}
function requestTagMarkup(tag,prefix="需要"){const meta=TAG_META[tag]||{icon:"◇",label:tag};return`<span class="attribute-row request-tag-row" title="${meta.label}"><i>${meta.icon}</i><b>${prefix} ${meta.label}</b></span>`}
function requestAttributeMarkup(request){const rows=[];for(const [key,rule] of Object.entries(request.requiredStats||{})){if(rule.min!==undefined)rows.push(renderAttributeRow(key,rule.min,{prefix:"需要"}));if(rule.max!==undefined)rows.push(renderAttributeRow(key,rule.max,{prefix:"需要",valueText:`不高于 ${attributeDots(rule.max)}`}))}for(const tag of request.requiredItemTags||[])rows.push(requestTagMarkup(tag));for(const tag of request.preferredItemTags||[])rows.push(requestTagMarkup(tag,"喜欢"));for(const [key,rule] of Object.entries(request.dislikedStats||{}))rows.push(renderAttributeRow(key,rule.min||0,{prefix:"避免"}));for(const tag of request.dislikedItemTags||[])rows.push(requestTagMarkup(tag,"避免"));if((request.minDistinctComponents||1)>1)rows.push(`<span class="request-note">至少 ${request.minDistinctComponents} 件不同物件</span>`);if((request.minCompositionCategories||1)>1)rows.push(`<span class="request-note">覆盖 ${request.minCompositionCategories} 种房间组成</span>`);if(request.difficulty>=4)rows.push('<span class="request-note">需求含糊 · 没有唯一答案</span>');return rows.join("")}
function shuffle(items,random=Math.random){const copy=[...items];for(let index=copy.length-1;index>0;index--){const target=Math.floor(random()*(index+1));[copy[index],copy[target]]=[copy[target],copy[index]]}return copy}
function chooseRequestTemplate(npc,random=Math.random,day=campaignState.day){const dayPool=requestPoolForDay(npc,day),recent=new Set(recentRequestHistory.slice(-3)),available=dayPool.filter(item=>!recent.has(`${npc.id}|${item.id}`)),pool=available.length?available:dayPool;return pool[Math.floor(random()*pool.length)]}
function syncNextMainNpc(){campaignState.nextMainNpc=requestQueue[0]?.npc||null;return campaignState.nextMainNpc}
function prepareDayQueue(shuffleOrder=false,random=Math.random,day=campaignState.day){requestQueue.splice(0);const order=shuffleOrder?shuffle(npcDatabase,random):[...npcDatabase];for(const npc of order)requestQueue.push({npc,template:chooseRequestTemplate(npc,random,day)});syncNextMainNpc();return requestQueue}
const FIRST_DAY_GUIDE=Object.freeze({opening:Object.freeze(["child","cold-guest"]),early:Object.freeze(["child","cold-guest","insomniac","elder","oddity-lover"]),middle:Object.freeze(["mechanic","dreamwalker"]),final:"mystery"});
function pickFromPool(pool,random=Math.random){return pool.splice(Math.min(pool.length-1,Math.floor(random()*pool.length)),1)[0]}
function easiestRequestTemplate(npc,random=Math.random,day=campaignState.day){const dayPool=requestPoolForDay(npc,day),minimum=Math.min(...dayPool.map(template=>template.difficulty)),pool=dayPool.filter(template=>template.difficulty===minimum);return pool[Math.min(pool.length-1,Math.floor(random()*pool.length))]}
function prepareFirstDayQueue(random=Math.random){requestQueue.splice(0);const byId=new Map(npcDatabase.map(npc=>[npc.id,npc])),opening=FIRST_DAY_GUIDE.opening.map(id=>byId.get(id)).filter(Boolean),first=pickFromPool(opening,random),early=FIRST_DAY_GUIDE.early.map(id=>byId.get(id)).filter(npc=>npc&&npc.id!==first.id),second=pickFromPool(early,random),guided=[first,second,...shuffle(early,random)],used=new Set(guided.map(npc=>npc.id)),middle=shuffle(FIRST_DAY_GUIDE.middle.map(id=>byId.get(id)).filter(npc=>npc&&!used.has(npc.id)),random),finalNpc=byId.get(FIRST_DAY_GUIDE.final),order=[...guided,...middle,...(finalNpc?[finalNpc]:[])];order.forEach((npc,index)=>requestQueue.push({npc,template:index<2?easiestRequestTemplate(npc,random,1):chooseRequestTemplate(npc,random,1)}));syncNextMainNpc();return requestQueue}
function ensureArchive(npc,request){let archive=customerArchive.get(npc.id);if(!archive){archive={npcId:npc.id,name:npc.name,portrait:npc.visualType,status:"MET",firstRequest:clonePlain(request),firstScore:null,bestScore:0,bestSolution:null,attemptCount:0,stayCount:0,rejectedStayCount:0,lastStayResult:null,lastStayAt:null,knownPreferences:[],knownDislikes:[],solutionHistory:[],firstCompletedAt:null,lastVisitedAt:Date.now(),lastFeedback:[],lastEmotion:"NEUTRAL",lastEmotionReasons:[]};customerArchive.set(npc.id,archive)}else{archive.status=archive.status==="UNKNOWN"?"MET":archive.status;archive.stayCount??=0;archive.rejectedStayCount??=0;archive.lastVisitedAt=Date.now()}renderCustomerArchive();return archive}
function renderCampaignProgress(){if(typeof document==="undefined")return;const total=npcDatabase.length,done=campaignState.mainProgress,current=campaignState.currentNpc;document.getElementById("day-number").textContent=String(campaignState.day);document.getElementById("guest-progress").textContent=`${Math.min(done+(campaignState.gameMode===GAME_MODES.MAIN?1:0),total)} / ${total}`;document.getElementById("current-guest-name").textContent=current?.name||(campaignState.gameMode===GAME_MODES.INTERMISSION?"营业空档":campaignState.gameMode===GAME_MODES.CLEARING_ROOM?"正在撤场":"暂无");const list=document.getElementById("completed-guest-list");list.replaceChildren();const completed=[...customerArchive.values()].filter(item=>item.status==="COMPLETED");if(!completed.length){const empty=document.createElement("span");empty.textContent="尚无";list.append(empty)}else for(const record of completed){const item=document.createElement("span");item.textContent=`✓ ${record.name}`;list.append(item)}document.getElementById("game-mode-label").textContent=campaignState.gameMode;document.getElementById("intermission-panel").hidden=campaignState.gameMode!==GAME_MODES.INTERMISSION;document.getElementById("request-card").hidden=[GAME_MODES.INTERMISSION,GAME_MODES.CLEARING_ROOM].includes(campaignState.gameMode)||!campaignState.currentNpc;document.getElementById("next-customer").disabled=campaignState.gameMode!==GAME_MODES.INTERMISSION||!campaignState.nextMainNpc;document.getElementById("auto-next-customer").checked=campaignState.autoNextCustomer;document.getElementById("exit-replay").hidden=campaignState.gameMode!==GAME_MODES.REPLAY}
function setRoomNPCState(state,evaluation,emotionResult=null){if(typeof document==="undefined")return;const roomNpc=document.getElementById("room-npc"),bubble=document.getElementById("room-npc-speech"),emote=document.getElementById("room-npc-emote"),stage=document.getElementById("room-stage");if(!roomNpc||!stage)return;const target=evaluation?.item||roomState.light.at(-1)||roomParts()[0],rating=state==="WAITING_FOR_CONFIRMATION"?evaluation?.score:null,emotion=emotionResult?.finalEmotion||campaignState.finalEmotion||"NEUTRAL",mood=emotion.toLowerCase();if(target){const roleItems=roomState[target.roomRole]||[],position=roomPartPosition(target,Array.isArray(roleItems)?roleItems.indexOf(target):0),targetPixel=stage.clientWidth*(position.x/100),beside=targetPixel<stage.clientWidth*.64?55:-55,emotionStep=["scared","disappointed"].includes(mood)?-18:0;roomState.inspectionTargetId=target.runtimeId;roomNpc.style.setProperty("--npc-target-x",`${Math.max(78,Math.min(stage.clientWidth-70,targetPixel+beside+emotionStep))}px`)}roomNpc.dataset.state=state;roomNpc.dataset.mood=mood;roomNpc.dataset.visual=campaignState.currentNpc?.visualType||"guest";roomNpc.dataset.rating=rating??"";const visible=["WALKING_TO_ROOM","INSPECTING","REACTING","WAITING_FOR_CONFIRMATION"].includes(state),targetX=roomNpc.style.getPropertyValue("--npc-target-x")||"90px";roomNpc.style.opacity=visible?"1":"0";roomNpc.style.transform=state==="LEAVING"?`translateX(calc(${targetX} + 190px))`:visible?`translateX(${targetX})`:"translateX(0)";const showEmote=["REACTING","WAITING_FOR_CONFIRMATION"].includes(state);emote.hidden=!showEmote;emote.textContent=({happy:"★",relaxed:"⌣",surprised:"!",confused:"?",scared:"!",angry:"♨",disappointed:"…",neutral:"·"})[mood]||"·";bubble.hidden=true}
function renderRequestCard(){if(typeof document==="undefined")return;const request=questState.request,npc=campaignState.currentNpc;if(!request||!npc)return;document.getElementById("request-card").dataset.visual=npc.visualType;document.getElementById("request-title").textContent=request.title;document.getElementById("request-npc-name").textContent=npc.name;document.getElementById("request-difficulty").textContent=`${campaignState.gameMode} · LEVEL ${request.difficulty}`;document.getElementById("npc-speech").textContent=requestDialogueForVisit(npc,request);document.getElementById("request-tags").innerHTML=requestAttributeMarkup(request);renderCampaignProgress()}
function renderFeedback(){if(typeof document==="undefined")return;const panel=document.getElementById("feedback-panel"),line=document.getElementById("feedback-line"),progress=document.getElementById("feedback-progress"),stars=document.getElementById("feedback-stars"),confirm=document.getElementById("confirm-feedback"),next=document.getElementById("feedback-next"),npc=campaignState.currentNpc;panel.hidden=!feedbackState.lines.length;panel.classList.toggle("active",!panel.hidden);if(panel.hidden)return;document.getElementById("feedback-speaker-name").textContent=npc?.name||"客人";document.getElementById("feedback-portrait").dataset.visual=npc?.visualType||"guest";line.textContent=feedbackState.expanded?feedbackState.lines.join("\n"):feedbackState.lines[Math.max(0,feedbackState.index)]||"";line.classList.toggle("expanded",feedbackState.expanded);progress.textContent=feedbackState.complete?"":`${feedbackState.index+1} / ${feedbackState.lines.length}`;stars.hidden=!feedbackState.starsVisible;stars.textContent="★".repeat(feedbackState.evaluation?.score||0)+"☆".repeat(3-(feedbackState.evaluation?.score||0));confirm.hidden=!feedbackState.complete;next.hidden=feedbackState.complete||feedbackState.expanded;next.textContent=feedbackState.index>=feedbackState.lines.length-1?"查看评价":"继续"}
function renderNPCState(state,detail={}){if(typeof document==="undefined")return;const npc=document.getElementById("pixel-npc"),speech=document.getElementById("npc-speech"),result=document.getElementById("request-result");npc.dataset.state=state;npc.dataset.visual=campaignState.currentNpc?.visualType||"guest";speech.hidden=state!=="WAITING";document.getElementById("inspect-room").disabled=!questState.active||state!=="WAITING";setRoomNPCState(state,detail.evaluation||feedbackState.evaluation,detail.emotionResult||feedbackState.emotionResult);if(state==="ENTERING")result.innerHTML="<b>新客人正在进店</b><span>门口的脚步正在靠近</span>";else if(state==="WAITING")result.innerHTML="<b>等待布置</b><span>房间、收纳和实验区都可以继续调整</span>";else if(state==="WALKING_TO_ROOM")result.innerHTML="<b>客人正在进入房间</b><span>正在走向最在意的物件</span>";else if(state==="INSPECTING")result.innerHTML="<b>体验中……</b><span>客人正在观察物件与整体氛围</span>";else if(state==="REACTING")result.innerHTML=campaignState.phase==="emotion"?"<b>客人有了反应</b><span>先观察他的情绪，再听他说话</span>":"<b>客人正在说出感受</b><span>先听完反馈，评分会在最后出现</span>";else if(state==="WAITING_FOR_CONFIRMATION")result.innerHTML="<b>评价已经说完</b><span>点击“知道了”后客人才会离开</span>";else if(state==="LEAVING")result.innerHTML="<b>客人正在离开</b><span>离开房间后才会开始撤场</span>";renderRequestCard();renderFeedback()}
npcStateMachine.onChange=(state,detail={})=>{campaignState.transitionHistory.push({npcId:campaignState.currentNpc?.id||null,state,phase:campaignState.phase,emotion:detail.emotionResult?.finalEmotion||null,mode:campaignState.gameMode,at:Date.now()});renderNPCState(state,detail)};
function acknowledgeRequest(){if(!questState.active)return false;if(npcStateMachine.state==="REQUESTING"){campaignState.phase="building";npcStateMachine.setState("BUILDING")}return npcStateMachine.state==="BUILDING"}
function startNPCVisit(withTimers=true){questState.active=true;campaignState.entryEmotion="NEUTRAL";campaignState.finalEmotion="NEUTRAL";campaignState.phase="request-arrival";renderRequestCard();npcStateMachine.setState("ENTERING");const arrive=()=>{campaignState.phase="building";npcStateMachine.setState("BUILDING")};if(withTimers&&typeof window!=="undefined")window.setTimeout(arrive,QUEUE_TIMING.enter);else arrive();return npcStateMachine.state}
function pauseNextNpcTimer(){const timer=campaignState.intermissionTimer;if(timer){clearTimeout(timer.hint);clearTimeout(timer.arrival)}campaignState.intermissionTimer=null;return true}
function autoNextCustomerTick(withTimers=true){if(campaignState.gameMode!==GAME_MODES.INTERMISSION||!campaignState.autoNextCustomer||campaignState.blockingModal||campaignState.currentNpc||Date.now()-(campaignState.intermissionStartedAt||0)<MIN_INTERMISSION_TIME)return false;return requestNextNpc(withTimers,{automatic:true})}
function scheduleNextNpcTimer(duration=INTERMISSION_DURATION){pauseNextNpcTimer();if(campaignState.gameMode!==GAME_MODES.INTERMISSION||!campaignState.autoNextCustomer||campaignState.blockingModal||!campaignState.nextMainNpc)return false;const wait=Math.max(MIN_INTERMISSION_TIME,duration);if(typeof window==="undefined")return true;const hint=window.setTimeout(()=>{if(campaignState.gameMode===GAME_MODES.INTERMISSION&&!campaignState.blockingModal){const notice=document.getElementById("queue-notice");notice.textContent="门铃轻轻晃了一下，好像快有客人来了……";notice.hidden=false}},Math.max(MIN_INTERMISSION_TIME,Math.round(wait*.7)));const arrival=window.setTimeout(()=>autoNextCustomerTick(true),wait);campaignState.intermissionTimer={hint,arrival};return true}
