  const emotionNames={NEUTRAL:"普通",HAPPY:"开心",RELAXED:"放松",SURPRISED:"惊讶",CONFUSED:"困惑",SCARED:"害怕",ANGRY:"生气",DISAPPOINTED:"失望"},emotionIcons={NEUTRAL:"·",HAPPY:"😊",RELAXED:"😌",SURPRISED:"😮",CONFUSED:"🤔",SCARED:"😨",ANGRY:"😠",DISAPPOINTED:"😞"},grid=document.getElementById("archive-grid"),detail=document.getElementById("archive-detail");
