    const archive=customerArchive.get(npc.id),button=document.createElement("button");button.type="button";button.className=`archive-card status-${archive?.status?.toLowerCase()||"unknown"}`;
    const stayText=archive?.lastStayResult==="accepted"?"已入住":archive?.lastStayResult==="rejected"?"没住下":"到过前台";
    button.innerHTML=archive?`<i data-portrait="${npc.visualType}"></i><b>${npc.name}</b><span>${emotionIcons[archive.lastEmotion]||"·"} ${stayText} · 入住 ${archive.stayCount||0} 次</span>`:`<i></i><b>???</b><span>尚未来访</span>`;
