function showHint(now=Date.now()){const elapsed=now-reactorState.lastProgressAt;if(elapsed<15000)return 0;const hint=typeof document!=="undefined"?document.getElementById("idle-hint"):null,key=strongestRequestedAttribute(),opportunities=getAvailableBaseIds().map(id=>({id,count:availableReactionCount(id),relevance:calculateTaskRelevance(elementLibrary[id])})).filter(item=>item.count).sort((a,b)=>b.relevance-a.relevance||b.count-a.count);let stage=elapsed>=45000?3:elapsed>=30000?2:1;reactorState.hintStage=stage;if(hint){if(stage===1)hint.textContent=key?`客人似乎更在意${ATTRIBUTE_UI[key].icon}${ATTRIBUTE_UI[key].label}。`:requestHints[campaignState.currentNpc?.id]||hints[0];else if(stage===2)hint.textContent=opportunities.length?`场上已经出现反应机会；留意元素池中发亮的线索。`:"试着加入一种与当前需求属性相近的元素。";else hint.textContent=opportunities.length?`可以重点观察：${opportunities.slice(0,2).map(item=>elementLibrary[item.id].label).join("、")}。`:hints[1];hint.hidden=false}return stage}
