function findSafeSpawnPosition(elementOrId,preferredX=null){
  const element=typeof elementOrId==="string"?elementLibrary[elementOrId]:elementOrId,canvas=reactorState.canvas;
  if(!element||!canvas)return null;
  const radius=30+Math.min(element.level,6)*5,columns=7,margin=radius+12,candidates=[];
  for(const y of [margin,margin+58])for(let index=0;index<columns;index++){
    const x=margin+(canvas.width-margin*2)*(index/(columns-1));
    if(pointInTrash({x,y}))continue;
    const clearance=activeBodies().reduce((best,body)=>Math.min(best,Math.hypot(x-body.x,y-body.y)-body.radius-radius),Infinity);
    const preference=Number.isFinite(preferredX)?Math.abs(x-preferredX)*.025:0;
    candidates.push({x,y,clearance,score:clearance-preference});
  }
  const safe=candidates.filter(candidate=>candidate.clearance>=8).sort((a,b)=>b.score-a.score)[0];
  return safe?{x:safe.x,y:safe.y}:null;
}

function showTemporaryPartners(body,duration=1800){
  const token=Date.now()+Math.random();reactorState.partnerHintToken=token;
  reactorState.libraryPreviewTargets=activeBodies().filter(target=>target!==body&&canReact(body,target)).map(target=>({runtimeId:target.runtimeId,known:discoveryBook.discovered.has(reactionRules[reactionKey(body.id,target.id)])}));
  if(typeof window!=="undefined")window.setTimeout(()=>{if(reactorState.partnerHintToken===token&&!reactorState.grabbedBody){reactorState.libraryPreviewTargets=[];reactorState.partnerHintToken=null}},duration);
  return reactorState.libraryPreviewTargets;
}

