function auditNpcItemReactionCoverage(){const items=Object.values(elementLibrary).filter(item=>item.level>1&&item.resultType!=="roomEvolution");return npcDatabase.map(npc=>{const pools=TAG_REACTION_POOLS[npc.id]||{},specials=SPECIAL_REACTIONS[npc.id]||{},requests=[1,2,3].flatMap(day=>requestPoolForDay(npc,day));let attributeHits=0,tagRuleHits=0,categoryDialogueHits=0,specialHits=0,covered=0;for(const item of items){const tags=componentTags(item),attribute=Object.values(item.attributes||{}).some(Boolean)&&requests.some(request=>[...Object.keys(request.requiredStats||{}),...Object.keys(request.preferredStats||{}),...Object.keys(request.dislikedStats||{})].some(key=>(item.attributes?.[key]||0)!==0)),tagRule=requests.some(request=>tags.some(tag=>[...(request.requiredItemTags||[]),...(request.preferredItemTags||[]),...(request.dislikedItemTags||[])].includes(tag))),category=tags.some(tag=>pools[tag]?.length),special=Boolean(specials[item.id]);if(attribute)attributeHits++;if(tagRule)tagRuleHits++;if(category)categoryDialogueHits++;if(special)specialHits++;if(attribute||tagRule||category||special)covered++}return{npcId:npc.id,name:npc.name,total:items.length,attributeHits,tagRuleHits,categoryDialogueHits,specialHits,coverage:Math.round(covered/items.length*100),categoryDialogueCoverage:Math.round(categoryDialogueHits/items.length*100),tagPoolCount:Object.keys(pools).length,specialReactionCount:Object.keys(specials).length}})}
function elementUtilizationAudit(){const items=Object.values(elementLibrary).filter(item=>item.level>1||item.roomRole||item.resultType==="roomEvolution"),strict=[],contextual=[],unused=[];for(const item of items){let strong=Object.values(SPECIAL_REACTIONS).some(table=>table[item.id]);for(const npc of npcDatabase)for(let day=1;day<=3;day++)for(const request of requestPoolForDay(npc,day))if(calculateComponentRelevance(item,request)>=.75)strong=true;const category=Object.values(TAG_REACTION_POOLS).some(pool=>componentTags(item).some(tag=>pool[tag]?.length));if(strong)strict.push(item.id);else if(category)contextual.push(item.id);else unused.push(item.id)}return{total:items.length,strictCount:strict.length,contextualCount:contextual.length,coveredCount:strict.length+contextual.length,strict,contextual,unused}}

